export function morphHtml(target, html) {
    const next = document.createElement('template');
    next.innerHTML = html;
    morphChildren(target, next.content);
}
function morphChildren(from, to) {
    const have = [...from.childNodes];
    const want = [...to.childNodes];
    want.forEach((node, i) => {
        const old = have[i];
        if (old === undefined)
            from.appendChild(node);
        else if (old.nodeType === node.nodeType && old.nodeName === node.nodeName)
            morphNode(old, node);
        else
            from.replaceChild(node, old);
    });
    for (const extra of have.slice(want.length))
        from.removeChild(extra);
}
function morphNode(old, node) {
    if (!(old instanceof Element) || !(node instanceof Element)) {
        if (old.nodeValue !== node.nodeValue)
            old.nodeValue = node.nodeValue;
        return;
    }
    for (const { name } of [...old.attributes])
        if (!node.hasAttribute(name))
            old.removeAttribute(name);
    for (const { name, value } of [...node.attributes])
        if (old.getAttribute(name) !== value)
            old.setAttribute(name, value);
    morphChildren(old, node);
}
